_PN = [("Noy, umikot ka sa bahay-bahay at humingi ka ng abuloy.", "Noy, go from house to house and ask for donations."), ("Pumanaw na si Ninong Serafin mo.", "Your godfather Serafin has passed away."), ("Pakisabi mo sa mga makikiramay na sa punerarya Villa ang burol.", "Please tell those who will extend condolences that the wake is at Villa Funeral Home."), ("Ipaalala mo, magpapamisa din tayo.", "Remind them that we will also offer a mass."), ("Tisay, bumili ka ng lobo.", "Tisay, buy a balloon."), ("Nanganak na si Mareng Dolor.", "Mareng Dolor has given birth."), ("Iniluwal niya nang normal ang bata.", "She gave birth to the child normally."), ("Hawig daw sa ama.", "The baby reportedly looks like the father."), ("Binyag pala ni Xavier.", "So it is Xavier’s baptism."), ("Bumili ka ng keyk. Idaan mo sa bahay nila agad.", "Buy a cake. Drop it off at their house right away."), ("Ding, dumaan ka sa bahay ni Tinoy, ’yung naulilang anak ni Aling Ining.", "Ding, pass by the house of Tinoy, the orphaned child of Aling Ining."), ("Ibigay mo ’yung koronang bulaklak.", "Give him the floral wreath."), ("Pakisabi na nakikiramay ang buong barangay sa pagyao ni Aling Ining.", "Please say that the whole barangay extends its condolences on the passing of Aling Ining."), ("Itanong mo na rin kung kailan ang libing.", "Also ask when the burial is.")]
