# ------------------------------------------------------------------ 3 gerunds
_GX = [("Simbolo ito ng pagdadalamhati.", "This is a symbol of mourning."), ("Ang pagbababang-luksa ay nag-uumpisa pagkatapos ng isang taon.", "The (end of) grief starts after one year."), ("Paggunita ito sa pagpanaw ng mga mahal sa buhay.", "This is a remembrance of those who died."), ("Sa mga Kristiyano puwede ang pag-eembalsamo.", "To Christians embalming is allowed."), ("Bawal ang pag-eembalsamo sa labi.", "Embalming the remains is forbidden."), ("Pakisabi na nakikiramay ang buong barangay sa pagyao ni Aling Ining.", "Please inform that the entire barangay is extending its condolences on the passing of Aling Ining.")]
_GMAG = [("magdalamhati", "dalamhati", "pagdadalamhati"), ("magbabang-luksa", "babang-luksa", "pagbababang-luksa"), ("mag-embalsamo", "embalsamo", "pag-eembalsamo")]
_GUM = [("gumunita", "gunita", "paggunita"), ("yumao", "yao", "pagyao"), ("bumili", "bili", "pagbili"), ("pumili", "pili", "pagpili")]
_INV = [("idaan", "daan", "idinaan", "idinadaan", "dadaanin"), ("iniluwal", "luwal", "iniluwal", "iniluluwal", "luluwalin"), ("pinapaliguan", "ligo", "pinaliguan", "pinapaliguan", "papaliguan"), ("binabalutan", "balot", "binalutan", "binabalutan", "babalutan"), ("dinadasalan", "dasal", "dinasalan", "dinadasalan", "dadasalan")]
_ACT2 = [("pagdadalamhati", "magdalamhati", "act of grieving (the book’s key says “act of showing sympathy”)"), ("pagbababang-luksa", "magbabang-luksa", "act of ending the mourning period"), ("paggunita", "gumunita", "act of remembering (remembrance)"), ("pag-eembalsamo", "mag-embalsamo", "act of embalming"), ("pagpanaw", "pumanaw", "act of dying, leaving loved ones"), ("pagdarasal", "magdasal", "act of praying"), ("pagyao", "yumao", "the passing of, act of dying"), ("pagdiriwang", "magdiwang", "act of celebrating")]
_A2S = [("Umiyak sila sa pagdadalamhati.", "They cried in their mourning."), ("Magsusuot ako ng puti hanggang sa pagbababang-luksa namin.", "I will wear white until the end of our mourning period."), ("Masaya ang naging paggunita nila sa buhay ni Dra. Del Mundo.", "Their remembrance of the life of Dr. Del Mundo was happy."), ("Maingat at maayos ang pag-eembalsamo.", "The embalming is careful and neat."), ("Nagdalamhati kami sa pagpanaw ng kaibigan ko.", "We grieved at the death of my friend."), ("Madalas ang pagdarasal nila.", "Their praying is frequent."), ("Hindi namin makalimutan ang pagyao ng biyenan ko.", "We cannot forget the passing of my mother-in-law."), ("Pupunta kami sa pagdiriwang ng kaarawan mo.", "We will go to the celebration of your birthday.")]
L3 = lesson(
    "C8 L3 · Gerunds from um and mag verbs",
    "Pag + salitang-ugat · pagdadalamhati · paggunita · pagyao",
    requires=[],
    cards=[
        card("Gerunds from um and mag", "Gerunds are words derived from verbs but used as nouns. English gerunds end in -ing: from go we get going, from vote voting, from run running (Marcie and I enjoyed going around the city; My favorite exercise is running). Tagalog gerunds are also derived from verbs but are formed differently. Examples from the reading:", examples=passage(_GX)),
        card("Rules for forming gerunds", "1. Tagalog gerunds use the prefix pag. Pag is a constant: it does not change whether the verb is doer-focus or object-focus, and it is followed by the root word of the verb. 2. When the gerund comes from a verb conjugated with mag, duplicate the first syllable of the root (magdalamhati → pagdadalamhati). 3. When the gerund comes from an um verb, do not duplicate the first syllable (gumunita → paggunita). 4. Not every word that begins with pag is a gerund: pagkatapos (after) is not; pagkain (food) is not a gerund depending on its use; pag-alis is not when it is used in the recent perfective tense; pagsusulit (test) is a noun. 5. The gerund is usually translated as a regular noun: pagpanaw, from pumanaw (die), is literally “dying,” but we simply say “death.” 6. The pattern in a phrase or a sentence is Ang/ng/sa + gerund + ng/ni/kay."),
        card("Gerunds from mag verbs", "", tables=[table(["Mag verb", "Root word", "Gerund"], [list(r) for r in _GMAG], say=[0, 1, 2])]),
        card("Gerunds from um verbs", "Note that these examples include vocabulary from the past.", tables=[table(["Um verb", "Root word", "Gerund"], [list(r) for r in _GUM], say=[0, 1, 2])]),
        card("Conjugation of in/hin/nin, pa/an/han/nan and an/han/nan verbs", "Although not yet discussed, a few verbs of these types appear as lexical terms. The book lists them just for reference:", tables=[table(["Verb", "Root word", "Past", "Present", "Future"], [list(r) for r in _INV], say=[0, 1, 2, 3, 4])]),
        card("Activity 2: eight sentences with gerunds (the book’s key)", "Write the gerund you hear, the verb it comes from and the translation of the gerund.", tables=[table(["Gerund", "Verb", "Translation"], [list(r) for r in _ACT2], say=[0, 1])]),
        card("The eight sentences (script)", "", examples=passage(_A2S)),
        card("Activities left out", "The audio."),
    ],
    exercises=uniq(
        tr_q(_GX) + rev_q(_GX) + tr_q(_A2S) + rev_q(_A2S)
        + [M(f"What is the gerund of {v} ({r})?", g, dd([x[2] for x in _GMAG + _GUM], g), f"{v} → {g}.") for v, r, g in _GMAG + _GUM]
        + [M(f"Which verb does the gerund {g} come from?", v, dd([x[1] for x in _ACT2], v), f"{g} ← {v}.") for g, v, _ in _ACT2]
        + [M(f"What does the gerund {g} mean?", t, dd([x[2] for x in _ACT2], t), f"{g}.") for g, v, t in _ACT2 if g != "pagdadalamhati"]
        + [M(f"What is the past of {v} (root {r})?", p, dd([x[2] for x in _INV], p), f"{v} → {p}.") for v, r, p, pr, f in _INV if p != v]
        + [M(f"What is the future of {v} (root {r})?", f, dd([x[4] for x in _INV], f), f"{v} → {f}.") for v, r, p, pr, f in _INV]
        + [M("What prefix do Tagalog gerunds use?", "pag", ["mag", "nag", "ma"], "pag."), M("Are gerunds from um verbs reduplicated?", "No, the first syllable is not duplicated", ["Yes, always", "Only before vowels", "Only in the past"], "paggunita."), M("Are gerunds from mag verbs reduplicated?", "Yes, the first syllable of the root is duplicated", ["No, never", "Only for um verbs", "Only in the future"], "pagdadalamhati."), M("Which word is NOT a gerund?", "pagkatapos", ["paggunita", "pagyao", "pagpanaw"], "pagkatapos means after."), M("What is the sentence pattern with a gerund?", "Ang/ng/sa + gerund + ng/ni/kay", ["Ang + verb + ng", "Ni + gerund + kay", "Sa + verb + ang"], "pattern.")]
        + [F("Simbolo ito ng ___. (mourning)", "pagdadalamhati", ["paggunita", "pagyao"], "mag verb: reduplicated."), F("___ ito sa pagpanaw ng mga mahal sa buhay. (remembrance)", "Paggunita", ["Pagdarasal", "Pagbili"], "um verb: not reduplicated."), F("Bawal ang ___ sa labi. (embalming)", "pag-eembalsamo", ["pagyao", "pagbili"], "pag-eembalsamo."), F("Hindi namin makalimutan ang ___ ng biyenan ko. (passing)", "pagyao", ["pagdarasal", "paggunita"], "pagyao."), F("Pupunta kami sa ___ ng kaarawan mo. (celebration)", "pagdiriwang", ["pagpanaw", "pag-eembalsamo"], "pagdiriwang.")]
    ),
)

