_CO = [("Melissa", "Nakikiramay ako sa pagyao ng panganay ninyong kapatid, Tina. Kailan at anong oras siya pumanaw? Ano ang ikinamatay niya?", "I extend my condolences on the passing of your eldest sibling, Tina. When and at what time did she pass away? What did she die of?"), ("Tina", "Salamat, Melissa. Pumanaw siya kagabi, alas-diyes ng gabi, dahil sa sakit sa puso.", "Thank you, Melissa. She passed away last night at ten o’clock because of a heart condition."), ("Melissa", "Kailan ang libing?", "When is the burial?"), ("Tina", "Wala pang iskedyul. Ie-embalsamo ang labi at magsisimula ang siyam na araw na nobena mamayang gabi.", "There is no schedule yet. The remains will be embalmed and the nine-day novena starts tonight."), ("Melissa", "Pakisabi sa mga magulang at kapatid mo na nakikiramay ako.", "Please tell your parents and siblings that I extend my condolences."), ("Tina", "Sige, sasabihin ko. Salamat sa tawag. Paalam.", "Okay, I will. Thank you for the call. Goodbye.")]
